        // By storing the original value once again, a refund is triggered (see
        // https://eips.ethereum.org/EIPS/eip-2200)
        _status = _NOT_ENTERED;
    }
}


/**
   Uniswap's TransferHelper contract, commit cfedb1f, 
   upgraded to version 0.8.9, rename safeTransferETH to safeTransferFLR
   https://github.com/Uniswap/uniswap-lib/blob/master/contracts/libraries/TransferHelper.sol
*/

// helper methods for interacting with FRC20 tokens and sending FLR that do not consistently return true/false
library TransferHelper {
    function safeApprove(address token, address to, uint256 value) internal {
        // bytes4(keccak256(bytes('approve(address,uint256)')));
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0x095ea7b3, to, value)
        );
        require(
            success && (data.length == 0 || abi.decode(data, (bool))),
            "TransferHelper::safeApprove: approve failed"
        );
    }

    function safeTransfer(address token, address to, uint256 value) internal {
        // bytes4(keccak256(bytes('transfer(address,uint256)')));
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0xa9059cbb, to, value)
        );
        require(
            success && (data.length == 0 || abi.decode(data, (bool))),
            "TransferHelper::safeTransfer: transfer failed"
        );
    }

    function safeTransferFrom(
        address token,
        address from,
        address to,
        uint256 value
    ) internal {
        // bytes4(keccak256(bytes('transferFrom(address,address,uint256)')));
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0x23b872dd, from, to, value)
        );
        require(
            success && (data.length == 0 || abi.decode(data, (bool))),
            "TransferHelper::transferFrom: transferFrom failed"
        );
    }

    function safeTransferFLR(address to, uint256 value) internal {
        (bool success, ) = to.call{ value: value }(new bytes(0));
        require(
            success,
            "TransferHelper::safeTransferFLR: FLR transfer failed"
        );
    }
}


interface IFRC20 {
    function totalSupply() external view returns (uint256);

    function balanceOf(address account) external view returns (uint256);

    function transfer(
        address recipient,
        uint256 amount
    ) external returns (bool);

    function allowance(
        address owner,
        address spender
    ) external view returns (uint256);

    function approve(address spender, uint256 amount) external returns (bool);

    function transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) external returns (bool);

    function name() external view returns (string memory);

    function symbol() external view returns (string memory);

    function decimals() external view returns (uint8);

    function increaseAllowance(
        address spender,
        uint256 addedValue
    ) external returns (bool);

    function decreaseAllowance(
        address spender,
        uint256 subtractedValue
    ) external returns (bool);

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(
        address indexed owner,
        address indexed spender,
        uint256 value
    );
}


interface IFarmingPoolStorage {
    function stakingToken() external view returns (address);
    function rewardToken() external view returns (address);
}


interface IFarmingPool is IFarmingPoolStorage {
    function stake(uint amount) external;
    function stakeFor(uint amount, address user) external;
    function withdraw(uint amount) external;
    function withdrawFor(uint amount, address user) external;
    function withdrawAndGetReward(uint amount) external;
    function withdrawAndGetRewardFor(uint amount, address user) external;
    function getReward() external;
    function exit() external;
    function earned(address account) external view returns (uint);
}


contract FarmingPoolStorage is Ownable, ReentrancyGuard, IFarmingPoolStorage {
    uint public DURATION;
    uint public PROTECTION_DURATION;

    address public override stakingToken;
    address public override rewardToken;
    uint256 public protectionPeriodFinish;
    uint256 internal _totalSupply;
    mapping(address => uint256) internal _balances;

    uint public startTime;
    uint public periodFinish;
    uint public rewardRate;
    uint public rewardRateFlr;
    uint public lastUpdateTime;
    uint public rewardPerTokenStored;
    uint public rewardPerFlrStored;
    mapping(address => uint) public userRewardPerTokenPaid;
    mapping(address => uint) public userRewardPerFlrPaid;
    mapping(address => uint) public rewards;
    mapping(address => uint) public rewardsFlr;

    event RewardAdded(uint reward);
    event Staked(address indexed user, uint amount);
    event Withdrawn(address indexed user, uint amount);
    event RewardPaid(address indexed user, uint reward);
    event FlrRewardPaid(address indexed user, uint reward);
    event UpdateDuration(uint indexed newDuration);
    event Received(address indexed sender, uint amount);
    event Rescue(address indexed recipient, uint amount);
    event RescueToken(address indexed recipient, address indexed token, uint amount);

    constructor(address owner) Ownable(owner) { }
}


contract FarmingPool is FarmingPoolStorage, IFarmingPool {    
    address public target;

    mapping (address => bool) public allowedCaller;
    event UpdateAllowedCaller(address indexed caller, bool indexed isAllowed);

    constructor() FarmingPoolStorage(address(0x1)) { }

    modifier checkStart() {
        require(block.timestamp >= startTime, "StaticPool: Not started");
        _;
    }

    modifier updateReward(address account) {
        _updateReward(account);
        _;
    }

    modifier onlyAllowedCaller() {
        require(allowedCaller[msg.sender], "StaticPool: Not allowed caller");
        _;
    }

    function initialize(address _rewardToken, address _stakeToken, uint _duration, uint _startTime, uint _rewardAmount) external onlyOwner {
        require(Address.isContract(_rewardToken), "StaticPool: _rewardToken is not a contract");
        require(Address.isContract(_stakeToken), "StaticPool: _stakeToken is not a contract");
        require(block.timestamp < _startTime && block.timestamp > periodFinish, 
            "StaticPool: Incorrect initialization time parameters");
        
        //we need _updateReward(address(0)) here in very corner case of pool reinitialization when stored lastUpdateTime is less than 
        //lastTimeRewardApplicable() meaning that there are some untracked rewards for the period from lastUpdateTime to lastTimeRewardApplicable()
        if (rewardRate > 0) _updateReward(address(0));
        
        stakingToken = _stakeToken;
        rewardToken = _rewardToken;

        startTime = _startTime;
        periodFinish = _startTime + _duration;
        DURATION = _duration;
        rewardRate = _rewardAmount / _duration;
        lastUpdateTime = _startTime;
        emit RewardAdded(_rewardAmount);

        PROTECTION_DURATION = 8 weeks;
        protectionPeriodFinish = periodFinish + PROTECTION_DURATION;
    }

    function totalSupply() public view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) public view returns (uint256) {
        return _balances[account];
    }

    function lastTimeRewardApplicable() public view returns (uint) {
        return block.timestamp < periodFinish ? block.timestamp : periodFinish; //return min value
    }

    function rewardPerToken() public view returns (uint) {
        if (totalSupply() == 0) {
            return rewardPerTokenStored;
        }
        return
            rewardPerTokenStored + (((lastTimeRewardApplicable() - lastUpdateTime) * rewardRate * 1e18) / totalSupply());
    }

    function earned(address account) public view returns (uint) {
        return
            balanceOf(account) * (rewardPerToken() - userRewardPerTokenPaid[account]) / 1e18  + rewards[account];
    }

    function stake(uint amount) external override {
        _stake(amount, msg.sender);
    }

    function stakeFor(uint amount, address user) external override onlyAllowedCaller {
        _stake(amount, user);
    }

    function withdraw(uint amount) external override  {
        _withdraw(amount, msg.sender);
    }

    function withdrawFor(uint amount, address user) external override onlyAllowedCaller {
        _withdraw(amount, user);
    }

    function withdrawAndGetReward(uint amount) external {
        _withdraw(amount, msg.sender);
        _getReward(msg.sender);
    }

    function withdrawAndGetRewardFor(uint amount, address user) external override onlyAllowedCaller {
        _withdraw(amount, user);
        _getReward(user);
    }

    function exit() external override {
        _withdraw(balanceOf(msg.sender), msg.sender);
        _getReward(msg.sender);
    }

    function getReward() external {
        _getReward(msg.sender);
    }

    function _getReward(address user) internal updateReward(user) checkStart nonReentrant {
        uint trueReward = earned(user);
        if (trueReward > 0) {
            rewards[user] = 0;
            TransferHelper.safeTransfer(rewardToken, user, trueReward);
            emit RewardPaid(user, trueReward);
        }
    }

    function _stake(uint amount, address user) private updateReward(user) checkStart {
        require(amount > 0, "StaticPool: Cannot stake 0");
        TransferHelper.safeTransferFrom(stakingToken, msg.sender, address(this), amount);
        _totalSupply += amount;
        _balances[user] += amount;
        emit Staked(user, amount);
    }

    function _withdraw(uint amount, address user) private updateReward(user) checkStart {
        require(amount > 0, "StaticPool: Cannot withdraw 0");
        require(amount <= balanceOf(user), "StaticPool: Cannot withdraw exceed the balance");
        TransferHelper.safeTransfer(stakingToken, user, amount);
        _totalSupply -= amount;
        _balances[user] -= amount;
        emit Withdrawn(user, amount);
    }

    function _updateReward(address account) private {
        rewardPerTokenStored = rewardPerToken();
        lastUpdateTime = lastTimeRewardApplicable();

        if (account != address(0)) {
            rewards[account] = earned(account);
            userRewardPerTokenPaid[account] = rewardPerTokenStored;
        }
    }

    function notifyRewardAmount(uint reward, uint newDuration) external onlyOwner {
        if (newDuration > 0) {
            require(newDuration > DURATION, "StaticPool: Duration is incorrect");
            DURATION = newDuration;
            emit UpdateDuration(newDuration);
        }
        _notifyRewardAmount(reward);
    }

    function _notifyRewardAmount(uint reward) private updateReward(address(0)) {
        require (block.timestamp > startTime, "StaticPool: Can't update reward for not started pool");
        if (block.timestamp >= periodFinish) {
            rewardRate = reward / DURATION;
        } else {
            uint remaining = periodFinish - block.timestamp;
            uint leftover = remaining * rewardRate;
            rewardRate = (reward + leftover) / DURATION;
        }
        lastUpdateTime = block.timestamp;
        periodFinish = block.timestamp + DURATION;
        emit RewardAdded(reward);
    }

    function updateAllowedCaller(address caller, bool isAllowed) external onlyOwner {
        require(caller != address(0), "StaticPool: Zero address");
        require(allowedCaller[caller] != isAllowed, "StaticPool: Already having the required status");
        allowedCaller[caller] = isAllowed;
        emit UpdateAllowedCaller(caller, isAllowed);
    }
    
    function rescue(address payable to_, uint256 amount_) external onlyOwner {
        require(to_ != address(0), "StaticPool: Cannot rescue to 0x0");
        require(amount_ > 0, "StaticPool: Cannot rescue 0");

        to_.transfer(amount_);
        emit Rescue(to_, amount_);
    }

    function rescue(address to_, address token_, uint256 amount_) external onlyOwner {
        require(to_ != address(0), "StaticPool: Cannot rescue to 0x0");
        require(amount_ > 0, "StaticPool: Cannot rescue 0");
        require(token_ != rewardToken, "StaticPool: Cannot rescue reward token");
        require(token_ != stakingToken, "StaticPool: Cannot rescue staking token");

        TransferHelper.safeTransfer(token_, to_, amount_);
        emit RescueToken(to_, address(token_), amount_);
    }

    function rescueUnclaimedTokens(address to_, uint256 amount_) external onlyOwner {
        require(block.timestamp >= protectionPeriodFinish, "StaticPool: not finished protection period");
        require(to_ != address(0), "StaticPool: Cannot rescue to 0x0");
        require(amount_ > 0, "StaticPool: Cannot rescue 0");

        TransferHelper.safeTransfer(rewardToken, to_, amount_);
    }
}
